function LevelOrderSum(root: TreeNode): array of integer;
begin
  if root = nil then
  begin
    Result := new integer[0];
    exit;
  end;

  var levelSums := new List<integer>;
  var queue := new Queue<TreeNode>;
  queue.Enqueue(root);

  while queue.Count > 0 do
  begin
    var levelSize := queue.Count;
    var levelSum := 0;

    for var i := 1 to levelSize do
    begin
      var node := queue.Dequeue;
      levelSum += node.val;

      if node.left <> nil then
        queue.Enqueue(node.left);
      if node.right <> nil then
        queue.Enqueue(node.right);
    end;

    levelSums.Add(levelSum);
  end;

  Result := levelSums.ToArray;
end;

function FindQuadruplets(nums: array of integer; n: integer): array of array of integer;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var quadruplets := new List<array of integer>;

  for var i := 0 to sorted.Length - 4 do
  begin
    if (i > 0) and (sorted[i] = sorted[i-1]) then
      continue;

    for var j := i + 1 to sorted.Length - 3 do
    begin
      if (j > i + 1) and (sorted[j] = sorted[j-1]) then
        continue;

      var left := j + 1;
      var right := sorted.Length - 1;

      while left < right do
      begin
        var sum := sorted[i] + sorted[j] + sorted[left] + sorted[right];

        if sum < 0 then
          left += 1
        else if sum > 0 then
          right -= 1
        else
        begin
          quadruplets.Add(|sorted[i], sorted[j], sorted[left], sorted[right]|);

          while (left < right) and (sorted[left] = sorted[left + 1]) do
            left += 1;
          while (left < right) and (sorted[right] = sorted[right - 1]) do
            right -= 1;

          left += 1;
          right -= 1;
        end;
      end;
    end;
  end;

  Result := quadruplets.ToArray;
end;

function GetSublists<T>(lst: array of T): array of array of T;
begin
  var subarrays := new List<array of T>;

  for var i := 0 to lst.Length - 1 do
    for var j := i to lst.Length - 1 do
    begin
      var subarray := new T[j - i + 1];
      for var k := i to j do
        subarray[k - i] := lst[k];
      subarrays.Add(subarray);
    end;

  Result := subarrays.ToArray;
end;

function IncrementNumber(num: int64): int64;
begin
  var digits := new List<integer>;
  var n := num;

  while n > 0 do
  begin
    digits.Insert(0, n mod 10);
    n := n div 10;
  end;

  if digits.Count = 0 then
    digits.Add(0);

  var carry := 1;
  for var i := digits.Count - 1 downto 0 do
  begin
    if carry = 0 then break;

    if digits[i] = 9 then
    begin
      digits[i] := 0;
      carry := 1;
    end
    else
    begin
      digits[i] += carry;
      carry := 0;
    end;
  end;

  if carry = 1 then
    digits.Insert(0, 1);

  var incremented: int64 := 0;
  foreach var d in digits do
    incremented := incremented * 10 + d;

  Result := incremented;
end;

function IncrementLastDigits(nums: array of integer): array of int64;
begin
  var resultList := new List<int64>;

  foreach var num in nums do
    resultList.Add(IncrementNumber(num));

  Result := resultList.ToArray;
end;

function IsSameRow(word: string): boolean;
begin
  var row1 := new HashSet<char>('qwertyuiop'.ToCharArray);
  var row2 := new HashSet<char>('asdfghjkl'.ToCharArray);
  var row3 := new HashSet<char>('zxcvbnm'.ToCharArray);

  var wordSet := word.ToLower.ToHashSet;
  Result := wordSet.IsSubsetOf(row1) or wordSet.IsSubsetOf(row2) or wordSet.IsSubsetOf(row3);
end;

function FindWords(words: array of string): array of string;
begin
  var singleRowWords := new List<string>;

  foreach var word in words do
    if IsSameRow(word) then
      singleRowWords.Add(word);

  Result := singleRowWords.ToArray;
end;

function PascalsTriangle(n: integer): array of array of integer;
begin
  var triangle := new List<array of integer>;

  for var i := 0 to n - 1 do
  begin
    var row := new List<integer>;

    for var j := 0 to i do
    begin
      if (j = 0) or (j = i) then
        row.Add(1)
      else
      begin
        var prevRow := triangle[i-1];
        row.Add(prevRow[j-1] + prevRow[j]);
      end;
    end;

    triangle.Add(row.ToArray);
  end;

  Result := triangle.ToArray;
end;

