end;

function Merge(left, right: array of integer): array of integer;
begin
  var merged := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < left.Length) and (j < right.Length) do
  begin
    if left[i] < right[j] then
    begin
      merged.Add(left[i]);
      i += 1;
    end
    else
    begin
      merged.Add(right[j]);
      j += 1;
    end;
  end;

  while i < left.Length do
  begin
    merged.Add(left[i]);
    i += 1;
  end;

  while j < right.Length do
  begin
    merged.Add(right[j]);
    j += 1;
  end;

  Result := merged.ToArray;
end;

function MergeSort(list: array of integer): array of integer;
begin
  if list.Length < 2 then
  begin
    Result := list;
    exit;
  end;

  var middle := list.Length div 2;
  var left := MergeSort(list[:middle]);
  var right := MergeSort(list[middle:]);

  Result := Merge(left, right);
end;

function MoveZeroes(nums: array of integer): array of integer;
begin
  var shifted := nums.ToArray;
  var nonZero := 0;

  for var i := 0 to shifted.Length - 1 do
    if shifted[i] <> 0 then
    begin
      var temp := shifted[nonZero];
      shifted[nonZero] := shifted[i];
      shifted[i] := temp;
      nonZero += 1;
    end;

  Result := shifted;
end;

function ReverseStringsAndList(strList: array of string): array of string;
begin
  var reversedList := new List<string>;

  for var i := strList.Length - 1 downto 0 do
  begin
    var reversed := '';
    for var j := strList[i].Length downto 1 do
      reversed += strList[i][j];
    reversedList.Add(reversed);
  end;

  Result := reversedList.ToArray;
end;

function Turn(digit: char): (string, string);
begin
  var d := StrToInt(digit.ToString);
  var up := ((d + 1) mod 10).ToString;
  var down := ((d - 1 + 10) mod 10).ToString;
  Result := (up, down);
end;

function Neighbors(state: string): IEnumerable<string>;
begin
  var neighborList := new List<string>;
  for var i := 1 to 4 do
  begin
    var digit := state[i];
    var (up, down) := Turn(digit);
    neighborList.Add(state.Substring(0, i-1) + up + state.Substring(i));
    neighborList.Add(state.Substring(0, i-1) + down + state.Substring(i));
  end;
  Result := neighborList;
end;

function FindMinimumMoves(deadends: array of string; target: string): integer;
begin
  var dead := new HashSet<string>(deadends);
  var queue := new Queue<(string, integer)>;
  queue.Enqueue(('0000', 0));
  var visited := new HashSet<string>;
  visited.Add('0000');

  while queue.Count > 0 do
  begin
    var (state, steps) := queue.Dequeue;

    if dead.Contains(state) then
      continue;

    if state = target then
    begin
      Result := steps;
      exit;
    end;

    foreach var nextState in Neighbors(state) do
    begin
      if not visited.Contains(nextState) then
      begin
        visited.Add(nextState);
        queue.Enqueue((nextState, steps + 1));
      end;
    end;
  end;

  Result := -1;
end;

